tool_calls.arguments_from_deltas:
{"command": "$rev = 1000+2000+3000+4000+5000+6000
$cost = 700+1400+2100+2800+3500+4200
$profit = $rev - $cost
$margin = [math]::Round($profit / $rev * 100, 1)
"TOTAL=$rev COST=$cost PROFIT=$profit MARGIN=$margin%"
# 逐月利润率
for ($m=1; $m -le 6; $m++) {
  $r = $m*1000; $c = $m*700
  $rt = if ($r -gt 0) { [math]::Round(($r-$c)/$r*100,1) } else { 0 }
  "M$m rev=$r cost=$c profit=$($r-$c) margin=$rt%"
}", "description": "计算销售数据合计与利润率"}

